    const turns:string[]=[];let reviewerEvidence:any;let controllerRef:Controller;const {controller,store}=await setup({discover:async()=>({version:'fixture',capabilities:{readOnlyReviewer:true},harnesses:[]}),submit:async input=>{turns.push(input.roleId);const output=input.roleId==='planner'?'Planner response':input.roleId==='orchestrator'?JSON.stringify({workerTask:'Make one bounded README.md note.'}):input.roleId==='reviewer'?JSON.stringify({verdict:'recommend',rationale:'Fixture review is clear.'}):'Worker completed';if(input.roleId==='reviewer')reviewerEvidence=input.config.reviewEvidence;const current=input.roleId==='reviewer'?(await store.load()).projects.flatMap(p=>p.tasks.flatMap(t=>t.runs)).find(r=>r.id===input.runId):undefined;const validation=current?(controllerRef as any).reviewerEvidencePackage(current).controllerValidation:undefined;return {externalId:`auto-${input.roleId}-${turns.length}`,responseId:`auto-response-${input.roleId}-${turns.length}`,sessionId:`auto-session-${input.roleId}`,status:'completed',outputText:output,actualModel:'model-fixture',requestedModel:'model-fixture',selectedHarnessId:'fixture',...(input.roleId==='reviewer'?{reviewerExecution:{mode:'read_only',mutationAttempted:false,validation}}:{})};}});controllerRef=controller;
